using System.Security.Cryptography;
using Bliss.Domain.CommandGateway;
using Bliss.Infrastructure.CommandGateway;
using Npgsql;
namespace Bliss.Tests.CommandGateway;
[Collection("Gateway inbox isolation")]
public sealed class GatewayTransportTests
{
 private const string Audience="local-gateway-test",ReceiptAudience="local-sender-test";
 private sealed record Fixture(GatewayEnvelope Envelope,GatewayPolicy Policy);
 private static Fixture Prepare(){var now=DateTimeOffset.UtcNow;var tenant=Guid.NewGuid();var sender=Guid.NewGuid();var recipient=Guid.NewGuid();return new(new("AGM-A2A/1",Guid.NewGuid(),Guid.NewGuid(),null,"AGM-LAUNCH-011",tenant,sender,recipient,GatewayMessageType.TaskAssignment,"LOCAL_MOCK","fixture-v1",Guid.NewGuid().ToString(),now,now.AddMinutes(10),"{\"b\":2,\"a\":1}"),new(true,tenant,sender,"fixture-v1",new HashSet<Guid>{recipient},new HashSet<GatewayMessageType>{GatewayMessageType.TaskAssignment}));}
 private static ValidatedGatewayMessage Valid(Fixture f)=>GatewayEnvelopeValidator.Validate(f.Envelope,new(true,f.Policy.TenantId,f.Policy.AgentId),f.Policy,DateTimeOffset.UtcNow);
 private static GatewaySignedRequest Sign(Fixture f,RSA rsa,DateTimeOffset? issued=null){var now=issued??DateTimeOffset.UtcNow;var request=new GatewaySignedRequest(f.Envelope,"fixture-workload",now,now.AddMinutes(1),"");return request with{Signature=Convert.ToBase64String(rsa.SignData(GatewayTransportCodec.RequestBytes(request,Valid(f).ContentHash,Audience),HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1))};}
 private static GatewayRequestVerifier Verifier(Fixture f,RSA rsa,string audience=Audience)=>new(audience,id=>id=="fixture-workload"?new(id,rsa.ExportSubjectPublicKeyInfoPem(),f.Policy):null);
 private static GatewaySignedReceipt Receipt(Fixture f,RSA rsa,Guid gateway){var now=DateTimeOffset.UtcNow;var receipt=new GatewaySignedReceipt(new(f.Envelope.MessageId,Valid(f).ContentHash,now,false,f.Policy.TenantId,f.Policy.AgentId,f.Envelope.RecipientAgentId,gateway),"fixture-gateway",now,now.AddMinutes(1),"");return receipt with{Signature=Convert.ToBase64String(rsa.SignData(GatewayTransportCodec.ReceiptBytes(receipt,ReceiptAudience),HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1))};}
 [Fact]public void Valid_signature_derives_identity_from_registration_and_canonical_property_order()
 {
  var f=Prepare();using var rsa=RSA.Create(2048);var request=Sign(f,rsa);var result=Verifier(f,rsa).Verify(request,DateTimeOffset.UtcNow);Assert.Equal(f.Policy.AgentId,result.Principal.AgentId);Assert.True(result.Principal.Authenticated);Assert.Equal(result.Message.ContentHash,Verifier(f,rsa).Verify(request with{Envelope=f.Envelope with{PayloadJson="{\"a\":1,\"b\":2}"}},DateTimeOffset.UtcNow).Message.ContentHash);
 }
 [Fact]public void Changed_body_key_time_signature_and_audience_are_refused()
 {
  var f=Prepare();using var rsa=RSA.Create(2048);using var attacker=RSA.Create(2048);var request=Sign(f,rsa);var verify=Verifier(f,rsa);
  foreach(var altered in new[]{request with{Envelope=f.Envelope with{PayloadJson="{\"a\":99}"}},request with{Envelope=f.Envelope with{IdempotencyKey="different"}},request with{Envelope=f.Envelope with{MessageId=Guid.NewGuid()}},request with{KeyId="unknown"},request with{IssuedAt=request.IssuedAt.AddSeconds(-1)},request with{Signature="not-base64"},request with{Signature=new string('A',1025)},Sign(f,attacker)})Assert.Throws<UnauthorizedAccessException>(()=>verify.Verify(altered,DateTimeOffset.UtcNow));
  Assert.Throws<UnauthorizedAccessException>(()=>Verifier(f,rsa,"wrong-audience").Verify(request,DateTimeOffset.UtcNow));Assert.Throws<UnauthorizedAccessException>(()=>verify.Verify(request with{Envelope=f.Envelope with{SenderAgentId=Guid.NewGuid()}},DateTimeOffset.UtcNow));
 }
 [Fact]public void Expired_future_oversized_windows_and_signature_outliving_envelope_are_refused()
 {
  var f=Prepare();using var rsa=RSA.Create(2048);var request=Sign(f,rsa);var now=DateTimeOffset.UtcNow;var verifier=Verifier(f,rsa);
  foreach(var altered in new[]{request with{ExpiresAt=now.AddSeconds(-1)},request with{IssuedAt=now.AddSeconds(6)},request with{ExpiresAt=request.IssuedAt.AddMinutes(3)},request with{ExpiresAt=request.IssuedAt},request with{Envelope=f.Envelope with{ExpiresAt=now.AddSeconds(20)}}})Assert.Throws<UnauthorizedAccessException>(()=>verifier.Verify(altered,now));
 }
 [Fact]public void Revoked_missing_mismatched_registration_and_weak_keys_fail_closed()
 {
  var f=Prepare();using var rsa=RSA.Create(2048);var request=Sign(f,rsa);GatewayWorkloadRegistration? registration=new("fixture-workload",rsa.ExportSubjectPublicKeyInfoPem(),f.Policy);var verifier=new GatewayRequestVerifier(Audience,_=>registration);Assert.NotNull(verifier.Verify(request,DateTimeOffset.UtcNow));registration=registration with{Policy=f.Policy with{Enabled=false}};Assert.Throws<InvalidOperationException>(()=>verifier.Verify(request,DateTimeOffset.UtcNow));registration=null;Assert.Throws<UnauthorizedAccessException>(()=>verifier.Verify(request,DateTimeOffset.UtcNow));registration=new("other",rsa.ExportSubjectPublicKeyInfoPem(),f.Policy);Assert.Throws<UnauthorizedAccessException>(()=>verifier.Verify(request,DateTimeOffset.UtcNow));using var weak=RSA.Create(1024);Assert.Throws<UnauthorizedAccessException>(()=>Verifier(f,weak).Verify(Sign(f,weak),DateTimeOffset.UtcNow));registration=new("fixture-workload","invalid-pem",f.Policy);Assert.Throws<UnauthorizedAccessException>(()=>verifier.Verify(request,DateTimeOffset.UtcNow));Assert.Throws<ArgumentException>(()=>new GatewayRequestVerifier("",_=>null));
 }
 [Fact]public void Signed_receipt_binds_all_acceptance_fields_and_cannot_be_a_request_signature()
 {
  var f=Prepare();using var rsa=RSA.Create(2048);var gateway=Guid.NewGuid();var receipt=Receipt(f,rsa,gateway);var trust=new GatewayReceiptTrust(receipt.KeyId,rsa.ExportSubjectPublicKeyInfoPem(),f.Policy.TenantId,gateway,true);Assert.Equal(f.Envelope.MessageId,GatewayReceiptVerifier.Verify(receipt,trust,ReceiptAudience,Valid(f),DateTimeOffset.UtcNow).MessageId);
  foreach(var altered in new[]{receipt with{Body=receipt.Body with{MessageId=Guid.NewGuid()}},receipt with{Body=receipt.Body with{ContentHash=new string('A',64)}},receipt with{Body=receipt.Body with{Replay=true}},receipt with{Body=receipt.Body with{AcceptedAt=receipt.Body.AcceptedAt.AddSeconds(-1)}},receipt with{Body=receipt.Body with{SenderAgentId=Guid.NewGuid()}},receipt with{Body=receipt.Body with{RecipientAgentId=Guid.NewGuid()}},receipt with{Body=receipt.Body with{TenantId=Guid.NewGuid()}},receipt with{Body=receipt.Body with{GatewayAgentId=Guid.NewGuid()}},receipt with{KeyId="wrong"},receipt with{Signature=Sign(f,rsa).Signature}})Assert.Throws<UnauthorizedAccessException>(()=>GatewayReceiptVerifier.Verify(altered,trust,ReceiptAudience,Valid(f),DateTimeOffset.UtcNow));
 }
 [Fact]public void Receipt_trust_scope_expiry_audience_and_unrelated_request_are_refused()
 {
  var f=Prepare();using var rsa=RSA.Create(2048);var gateway=Guid.NewGuid();var receipt=Receipt(f,rsa,gateway);var trust=new GatewayReceiptTrust(receipt.KeyId,rsa.ExportSubjectPublicKeyInfoPem(),f.Policy.TenantId,gateway,true);
  foreach(var changed in new[]{trust with{Enabled=false},trust with{TenantId=Guid.NewGuid()},trust with{GatewayAgentId=Guid.NewGuid()}})Assert.Throws<UnauthorizedAccessException>(()=>GatewayReceiptVerifier.Verify(receipt,changed,ReceiptAudience,Valid(f),DateTimeOffset.UtcNow));Assert.Throws<UnauthorizedAccessException>(()=>GatewayReceiptVerifier.Verify(receipt,trust,"wrong",Valid(f),DateTimeOffset.UtcNow));Assert.Throws<UnauthorizedAccessException>(()=>GatewayReceiptVerifier.Verify(receipt,trust,ReceiptAudience,Valid(Prepare()),DateTimeOffset.UtcNow));Assert.Throws<UnauthorizedAccessException>(()=>GatewayReceiptVerifier.Verify(receipt,trust,ReceiptAudience,Valid(f),receipt.ExpiresAt));
 }
 private static NpgsqlDataSource Data()=>NpgsqlDataSource.Create(Environment.GetEnvironmentVariable("BLISS_GATEWAY_TEST_POSTGRES")!);
 private static async Task<Fixture> PersistedFixture(NpgsqlDataSource data){var f=Prepare();await using var cmd=data.CreateCommand("INSERT INTO command_gateway.agents VALUES(@tenant,@sender),(@tenant,@recipient)");cmd.Parameters.AddWithValue("tenant",f.Policy.TenantId);cmd.Parameters.AddWithValue("sender",f.Policy.AgentId);cmd.Parameters.AddWithValue("recipient",f.Envelope.RecipientAgentId);await cmd.ExecuteNonQueryAsync();return f;}
 private static async Task<long> Count(NpgsqlDataSource data,Guid id){await using var cmd=data.CreateCommand("SELECT count(*) FROM command_gateway.messages WHERE message_id=@id");cmd.Parameters.AddWithValue("id",id);return (long)(await cmd.ExecuteScalarAsync())!;}
 [GatewayPostgresFact]public async Task Signed_concurrent_acceptance_returns_verifiable_durable_receipts_and_rejects_revoked_retry()
 {
  await using var data=Data();var f=await PersistedFixture(data);using var sender=RSA.Create(2048);using var gateway=RSA.Create(2048);var gatewayId=Guid.NewGuid();var registration=new GatewayWorkloadRegistration("fixture-workload",sender.ExportSubjectPublicKeyInfoPem(),f.Policy);var verifier=new GatewayRequestVerifier(Audience,_=>registration);var adapter=new LocalGatewayTransport(new(data),verifier,gateway,"fixture-gateway",ReceiptAudience,f.Policy.TenantId,gatewayId);var request=Sign(f,sender);var receipts=await Task.WhenAll(Enumerable.Range(0,12).Select(_=>adapter.Accept(request)));Assert.Single(receipts,r=>!r.Body.Replay);Assert.Single(receipts.Select(r=>r.Body.AcceptedAt).Distinct());var trust=new GatewayReceiptTrust("fixture-gateway",gateway.ExportSubjectPublicKeyInfoPem(),f.Policy.TenantId,gatewayId,true);Assert.All(receipts,r=>Assert.Equal(f.Envelope.MessageId,GatewayReceiptVerifier.Verify(r,trust,ReceiptAudience,Valid(f),DateTimeOffset.UtcNow).MessageId));Assert.Equal(1,await Count(data,f.Envelope.MessageId));
  await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>adapter.Accept(request with{Envelope=f.Envelope with{PayloadJson="{\"a\":3}"}}));registration=registration with{Policy=f.Policy with{Enabled=false}};await Assert.ThrowsAsync<InvalidOperationException>(()=>adapter.Accept(request));Assert.Equal(1,await Count(data,f.Envelope.MessageId));
 }
 [GatewayPostgresFact]public async Task Response_signing_failure_leaves_committed_acceptance_and_authenticated_retry_recovers_receipt()
 {
  await using var data=Data();var f=await PersistedFixture(data);using var sender=RSA.Create(2048);var gateway=RSA.Create(2048);using var restarted=RSA.Create();restarted.ImportParameters(gateway.ExportParameters(true));var gatewayId=Guid.NewGuid();var verifier=Verifier(f,sender);var broken=new LocalGatewayTransport(new(data),verifier,gateway,"fixture-gateway",ReceiptAudience,f.Policy.TenantId,gatewayId);gateway.Dispose();var request=Sign(f,sender);await Assert.ThrowsAsync<ObjectDisposedException>(()=>broken.Accept(request));Assert.Equal(1,await Count(data,f.Envelope.MessageId));var receipt=await new LocalGatewayTransport(new(data),verifier,restarted,"fixture-gateway",ReceiptAudience,f.Policy.TenantId,gatewayId).Accept(Sign(f,sender));Assert.True(receipt.Body.Replay);var trust=new GatewayReceiptTrust(receipt.KeyId,restarted.ExportSubjectPublicKeyInfoPem(),f.Policy.TenantId,gatewayId,true);Assert.NotNull(GatewayReceiptVerifier.Verify(receipt,trust,ReceiptAudience,Valid(f),DateTimeOffset.UtcNow));
  var unaccepted=await PersistedFixture(data);var deny=new LocalGatewayTransport(new(data),Verifier(unaccepted,sender),restarted,"fixture-gateway",ReceiptAudience,unaccepted.Policy.TenantId,gatewayId);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>deny.Accept(Sign(unaccepted,sender) with{Signature="invalid"}));Assert.Equal(0,await Count(data,unaccepted.Envelope.MessageId));
 }
}
